<script>
  import researchSummary from '$lib/research-summary.json';
  import { base } from '$app/paths';
  import report from '$lib/generated/report.json';
  import EvidenceBar from '$lib/EvidenceBar.svelte';
  import SmallBusinessTrend from '$lib/SmallBusinessTrend.svelte';
  let population = $state('All ever certified');
  const smallLabel = 'Documented or likely small';
  const remainingLabel = 'Documented not small, likely not small, or unknown';
  const isSmall = a => ['documented-small','likely-small'].includes(a.classification);
  const groupLabel = a => isSmall(a) ? smallLabel : remainingLabel;
  let unit = $state('providers');
  let status = $state('Certified');
  const basis = 'current';
  let query = $state('');
  let pathway = $state('All pathways');
  let evidence = $state('All evidence');
  let listing = $state('All listed');
  let year = $state('All years');
  let page = $state(1);
  const pathways = ['Rev5', '20x Pilot', '20x'];
  const labels = {'documented-small':'Documented small','likely-small':'Likely small','documented-not-small':'Documented other-than-small','likely-not-small':'Likely other-than-small',unknown:'Unknown'};
  const pct = n => n == null ? '—' : `${n.toFixed(1)}%`;
  const count = n => n.toLocaleString('en-US');
  const share = (n,total) => total ? n / total * 100 : 0;
  const reset = () => { page = 1; };
  let current = $derived(report.reports.groups.filter(r=>r.unit===unit && r.status===status && pathways.includes(r.pathway)));
  let annual = $derived(report.reports.annual.filter(r=>r.unit===unit && r.basis===basis && r.population===population && r.pathway==='All pathways'));
  let cohortTotal = $derived(report.reports.cohortTotals.find(r=>r.unit===unit && r.basis===basis && r.population===population));
  let nonPilot = $derived(report.offerings.filter(o=>!o.excluded&&o.pathway==='20x'&&o.currentCertified));
  let windows = $derived(report.reports.windows.filter(r=>r.unit===unit && r.basis===basis && r.pathway==='All pathways'));
  let filtered = $derived(report.offerings.filter(o=>!o.excluded && (listing==='All records'||listing==='All listed'&&o.currentListed||listing==='Certified'&&o.currentCertified||listing==='Initial Implementation'&&o.status===listing||listing==='Delisted'&&o.status==='No Status Found (Delisted)') && (pathway==='All pathways'||o.pathway===pathway) && (evidence==='All evidence'||(evidence==='small'?isSmall(o.currentAssessment):!isSmall(o.currentAssessment))) && (year==='All years'||o.firstCertification?.transition_date.startsWith(year)) && `${o.name} ${o.providerName} ${o.id}`.toLowerCase().includes(query.toLowerCase())));
  let pages = $derived(Math.max(1,Math.ceil(filtered.length/30)));
  let visible = $derived(filtered.slice((page-1)*30,page*30));
  const years = [...new Set(report.reports.annual.map(r=>r.year))].reverse();
  const safeUrl = url => typeof url==='string' && /^https?:\/\//i.test(url) ? url : undefined;
</script>

<svelte:head>
  <title>Small business in the FedRAMP Marketplace</title>
  <meta name="description" content="An independent, reproducible study of small business participation in FedRAMP Rev5 and 20x, with provider-level sources and explicit evidence gaps." />
</svelte:head>
<a class="skip" href="#main">Skip to content</a>
<header class="header"><div class="wrap masthead"><a class="brand" href="{base}/" aria-label="Marketplace small business home"><svg width="26" height="28" viewBox="0 0 26 28" aria-hidden="true"><path fill="currentColor" d="M0 17h6v11H0zM10 9h6v19h-6zM20 0h6v28h-6z"/></svg><span>Marketplace<br/><strong>Small business</strong></span></a><nav aria-label="Main navigation"><a href="#participation">Findings</a><a href="#evidence">Evidence</a><a href="{base}/methodology/">Methodology</a><a href="#downloads">Data ↓</a></nav></div></header>
<main id="main" class="wrap">
  <section class="hero" aria-labelledby="title"><div><p class="eyebrow">An independent research project · Updated {report.asOf}</p><h1>Who gets access<br/>to the federal cloud?</h1><p class="intro">Small business participation in the FedRAMP Marketplace, across Rev5, the 20x pilot, and the 20x program.</p><p>Explore the companies behind the products, the evidence of their size, and what certification trends can—and cannot—tell us.</p><a class="rule-link" href="#participation">Explore the findings <span aria-hidden="true">↓</span></a></div><aside class="hero-aside"><p class="eyebrow">The finding so far</p><h2>Participation is visible.<br/>The change in access is harder to establish.</h2><p>The evidence identifies <strong>{report.coverage.current.smallGroup} of {report.coverage.current.total}</strong> currently listed, identifiable commercial providers as documented or likely small ({pct(report.coverage.current.smallGroupPct)}).</p><p>Historical size is unknown for <strong>{pct(report.coverage.historical.unknownPct)}</strong> of providers in first-certification cohorts. These data alone cannot show that recent reforms caused access to improve.</p><a href="{base}/methodology/#limitations">Understand the evidence gaps ↗</a></aside></section>
  <div class="finding"><strong>Two groups, one denominator.</strong> Every percentage uses all eligible providers or products in that row. Unknowns are included with documented or likely not-small businesses in the second group. That grouping does not mean an unknown company was determined to be large.</div>

  <section id="participation" aria-labelledby="participation-title"><div class="section-head"><div><p class="eyebrow">01 / The current picture</p><h2 id="participation-title">Rev5 and 20x, side by side</h2></div><p>Current size evidence · current pathway and status</p></div><div class="controls"><label><span>Count</span><select bind:value={unit}><option value="providers">Distinct providers</option><option value="offerings">Product / package listings</option></select></label><label><span>Marketplace status</span><select bind:value={status}><option>Certified</option><option>Initial Implementation</option><option>All listed</option><option>Other pre-certification</option><option>Delisted</option></select></label></div>
    <div class="legend"><span><i class="swatch"></i>{smallLabel}</span><span><i class="swatch other"></i>{remainingLabel}</span></div><p class="unit-note">Each bar totals 100% of its row, not a count scale. The number at right is the green group: small count ÷ full row total.</p>
    {#each current as row (row.pathway)}<EvidenceBar {row} label={row.pathway==='20x'?'20x · non-pilot':row.pathway} {unit} />{/each}
    <div class="table-scroll"><table><caption>{status}: small business evidence, including unknowns in the denominator</caption><thead><tr><th scope="col">Pathway</th><th scope="col">Total {unit}</th><th scope="col">{smallLabel}</th><th scope="col">{remainingLabel}</th></tr></thead><tbody>{#each current as r (r.pathway)}<tr><th scope="row">{r.pathway==='20x'?'20x · non-pilot':r.pathway}</th><td>{r.total}</td><td>{r.smallGroup} <small>({pct(r.smallGroupPct)})</small></td><td>{r.remainingGroup} <small>({pct(r.remainingGroupPct)}); includes {r.counts.unknown} unknown</small></td></tr>{/each}</tbody></table></div>
    <p class="note">Providers may appear in multiple pathways, so rows do not sum to a distinct-provider total. “Certified” includes certified offerings in remediation. Initial implementation is preparation, not certification. The source distinguishes “20x Pilot” from “20x”; pilot history is also retained in the downloads.</p>
  </section>

  <section aria-labelledby="nonpilot-title"><div class="section-head"><h2 id="nonpilot-title">The eight certified non-pilot 20x providers</h2></div><p>Targeted review found small-company testimony for Files.com and Bland AI, a probable small-business registry match for Wisedocs, and a relevant employee-based NAICS representation for Perplexity. These are likely assessments, not legal determinations. The other group includes unresolved size, rather than assuming every startup is small.</p><div class="table-scroll"><table><caption>Current pathway and current size evidence; Perplexity previously participated in the pilot</caption><thead><tr><th scope="col">Provider</th><th scope="col">Group</th><th scope="col">Evidence and limitations</th></tr></thead><tbody>{#each nonPilot as o (o.id)}<tr><th scope="row">{o.providerName}</th><td>{groupLabel(o.currentAssessment)}</td><td><details><summary>Sources and limitations</summary><p>{o.currentAssessment.reason}</p>{#each o.currentAssessment.evidence as e,i (i)}<small><a href={safeUrl(e.url)}>{e.kind}</a></small>{/each}</details></td></tr>{/each}</tbody></table></div></section>

  <section id="trends" aria-labelledby="trends-title"><div class="section-head"><div><p class="eyebrow">02 / A view over time</p><h2 id="trends-title">Certification cohorts by year</h2></div><p>First observed certification per product / package</p></div><div class="controls"><label><span>Count in annual and window reports</span><select bind:value={unit}><option value="providers">Distinct providers</option><option value="offerings">Product / package listings</option></select></label><label><span>Annual population</span><select bind:value={population}><option>All ever certified</option><option>Currently certified</option></select></label></div><p class="unit-note">Counting {unit}. Each cohort uses the most recent small-business assessment available in this snapshot ({report.asOf}), not size at certification. For providers, use their earliest product certification within each cohort.</p>
    <div class="finding" aria-live="polite"><strong>Most recent size assessment · snapshot {report.asOf} · {population.toLowerCase()}</strong>{cohortTotal.smallGroup} of {cohortTotal.total} {unit} ({pct(cohortTotal.smallGroupPct)}) are in the documented-or-likely-small group across all years, counted once. The second group contains {cohortTotal.remainingGroup}, including {cohortTotal.counts.unknown} with unknown size.</div>
    <SmallBusinessTrend rows={annual} {unit} asOf={report.asOf} />
    <div class="legend"><span><i class="swatch"></i>{smallLabel}</span><span><i class="swatch other"></i>{remainingLabel}</span></div><p class="unit-note">Each bar totals 100% of its row, not a count scale. The number at right is the green group: small count ÷ full row total.</p>
    <div class="year-bars">{#each annual as row (row.year)}<EvidenceBar {row} label={row.year+(row.partial?'*':'')} {unit} />{/each}</div>
    <details><summary>Annual counts and percentages</summary><div class="table-scroll"><table><caption>Annual certification cohorts · most recent size assessment ({report.asOf}) · {unit}</caption><thead><tr><th scope="col">Year</th><th scope="col">Total</th><th scope="col">{smallLabel}</th><th scope="col">{remainingLabel}</th><th scope="col">First-time providers</th></tr></thead><tbody>{#each annual as r (r.year)}<tr><th scope="row">{r.year}{r.partial?'*':''}</th><td>{r.total}</td><td>{r.smallGroup} ({pct(r.smallGroupPct)})</td><td>{r.remainingGroup} ({pct(r.remainingGroupPct)})<small>Includes {r.counts.unknown} unknown</small></td><td>{r.firstTimeProviders}</td></tr>{/each}</tbody></table></div></details><p class="note">* {report.asOf.slice(0,4)} is a partial year through {report.asOf}. Providers can appear in more than one annual row when different products first certify in different years; do not sum annual provider rows as a unique-business total. Product rows are additive. Source history is retrospective; “first-time” means first observed in these records, not proven first-ever participation. Historical pathways are the pathway recorded at certification, not necessarily today’s pathway.</p>
    <div class="callout"><h3>The latest 24 months<br/>versus the previous 24</h3><div><p>Equal-length windows make the comparison more useful than comparing a partial year with a complete one. They still do not control for pilot selection, impact level, policy timing, or changes in company size since certification.</p><div class="table-scroll"><table><caption>Most recent size assessment ({report.asOf}) · all ever-certified {unit}</caption><thead><tr><th scope="col">Window</th><th scope="col">Total</th><th scope="col">{smallLabel}</th><th scope="col">{remainingLabel}</th></tr></thead><tbody>{#each windows as r (r.label)}<tr><th scope="row">{r.label}<small>{r.start} to {new Date(Date.parse(r.endExclusive)-86400000).toISOString().slice(0,10)}</small></th><td>{r.total}</td><td>{r.smallGroup} ({pct(r.smallGroupPct)})</td><td>{r.remainingGroup} ({pct(r.remainingGroupPct)})<small>Includes {r.counts.unknown} unknown</small></td></tr>{/each}</tbody></table></div><p class="note">No causal conclusion: different evidence coverage can change the observed small-business share without any change in actual access.</p></div></div>
  </section>

  <section id="evidence" aria-labelledby="evidence-title"><div class="section-head"><div><p class="eyebrow">03 / Inspect the evidence</p><h2 id="evidence-title">Every product. Every assessment.</h2></div><a href="{base}/downloads/providers.csv" download>Download provider data ↓</a></div><p>Open a record for its reasoning and source links. The size classification belongs to the provider; product records retain separate status, pathway, and certification history.</p><div class="controls"><label class="control-search"><span>Search provider, product, or package ID</span><input type="search" bind:value={query} oninput={reset} placeholder="e.g. InfusionPoints" /></label><label><span>Pathway</span><select bind:value={pathway} onchange={reset}><option>All pathways</option>{#each pathways as p (p)}<option>{p}</option>{/each}<option>Unknown</option></select></label><label><span>Status</span><select bind:value={listing} onchange={reset}><option>All listed</option><option>Certified</option><option>Initial Implementation</option><option>Delisted</option><option>All records</option></select></label><label><span>Current size evidence</span><select bind:value={evidence} onchange={reset}><option>All evidence</option><option value="small">{smallLabel}</option><option value="remaining">{remainingLabel}</option></select></label><label><span>First certification year</span><select bind:value={year} onchange={reset}><option>All years</option>{#each years as y (y)}<option>{y}</option>{/each}</select></label></div>
    <p class="coverage-line" aria-live="polite">{count(filtered.length)} matching product records · showing {filtered.length?((page-1)*30)+1:0}–{Math.min(page*30,filtered.length)}</p>
    <div class="table-scroll"><table class="evidence-table"><caption>Provider and product evidence · government-operated services excluded</caption><thead><tr><th scope="col">Provider / product</th><th scope="col">Pathway / status</th><th scope="col">Current size / confidence</th><th scope="col">Reason &amp; sources</th></tr></thead><tbody>{#each visible as o (o.id)}<tr><th scope="row">{o.providerName}<small>{o.name||'Product name unavailable'}</small><small>{o.id} · {o.certClass}</small></th><td>{o.pathway}<small>{o.status}</small>{#if o.everPilot&&!o.pilot}<small>Previously in pilot</small>{/if}</td><td><span class="badge" class:documented-small={isSmall(o.currentAssessment)}>{groupLabel(o.currentAssessment)}</span><small>{o.currentAssessment.confidence} confidence</small></td><td><details><summary>View assessment</summary><p><strong>Underlying evidence:</strong> {labels[o.currentAssessment.classification]}</p><p>{o.currentAssessment.reason}</p>{#if o.currentAssessment.evidence.length}<ul>{#each o.currentAssessment.evidence as e,i (i)}<li><a href={safeUrl(e.url)} target="_blank" rel="noreferrer">{e.kind}</a>{#if e.legalName}<br/>{e.legalName}{/if}{#if e.primaryNaics}<br/>Primary NAICS: {e.primaryNaics}{/if}{#if e.uei}<br/>UEI: {e.uei}{/if}</li>{/each}</ul>{:else}<p>No qualifying source found. Registry and website searches were attempted for every resolved provider; the research log is in the repository.</p>{/if}<p><strong>At first certification:</strong> {o.firstCertification?.transition_date.slice(0,10)??'No event recorded'} · {groupLabel(o.historicalAssessment)}</p><p>Underlying historical evidence: {labels[o.historicalAssessment.classification]}</p><p>{o.historicalAssessment.reason}</p>{#each o.historicalAssessment.evidence as e,i (i)}<p><a href={safeUrl(e.url)} target="_blank" rel="noreferrer">Historical source: {e.kind}</a></p>{/each}<p>Marketplace flag: {o.marketplaceFlags.join(', ')||'Not supplied'}. Retained as a separate source field, not a legal finding.</p></details></td></tr>{/each}</tbody></table></div>{#if !filtered.length}<p class="empty">No records match these filters. Try a broader search or select all evidence.</p>{/if}<div class="pagination"><button disabled={page===1} onclick={()=>page--}>← Previous</button><span>Page {page} of {pages}</span><button disabled={page===pages} onclick={()=>page++}>Next →</button></div>
  </section>

  <section id="downloads" aria-labelledby="downloads-title"><div class="section-head"><div><p class="eyebrow">04 / Reuse and extend</p><h2 id="downloads-title">The data behind the page</h2></div><a href="https://github.com/pete-wai/marketplace-smb">View the repository ↗</a></div><div class="twocol"><div><h3>A reproducible snapshot</h3><p><strong>Deeper research:</strong> {researchSummary.individuallyReviewed} provider decisions individually reviewed; {researchSummary.changed} classifications or confidence levels changed. {researchSummary.unknown} providers remain unknown across the full inventory. Other records retain screening-level evidence. The downloads distinguish these review depths.</p><p>{count(report.coverage.offerings)} package identities and {count(report.coverage.providers)} resolved provider identities, including historical and delisted records. Every resolved provider was screened against public SBA search and its listed websites.</p><p class="note">{report.coverage.unresolvedIdentityOfferings} package identities could not be linked to a provider in retrieved exports, including {report.coverage.current.unresolvedIdentityOfferings} currently listed records. They remain in product totals. {report.coverage.excludedProviders} government operators ({report.coverage.excludedOfferings} products) are excluded from commercial participation rates.</p><a href="https://github.com/FedRAMP/marketplace-fedramp-gov-data/tree/{report.source.commit}">Marketplace source snapshot · {report.source.commit.slice(0,7)} ↗</a></div><div class="download-list">{#each [['research-ledger.csv','Research decisions and sources · CSV'],['research-ledger.json','Research coverage and evidence · JSON'],['research-changes.json','Before / after decisions · JSON'],['analysis.json','Complete dataset · JSON'],['providers.csv','Providers and evidence · CSV'],['offerings.csv','Products and historical assessments · CSV'],['groups.csv','Current pathway and status comparisons · CSV'],['annual.csv','Annual certification cohorts · CSV'],['cohortTotals.csv','Deduplicated all-years certification totals · CSV'],['windows.csv','Rolling 24-month comparisons · CSV'],['classes.csv','Certification class breakdown · CSV'],['marketplaceFlags.csv','Original Marketplace flags · CSV'],['status-events.csv','All status transitions · CSV']] as [file,label] (file)}<a href="{base}/downloads/{file}" download>{label}<span aria-hidden="true">↓</span></a>{/each}</div></div></section>
</main>
<footer><div class="wrap"><p><strong>Marketplace / Small business</strong><br/>Independent research. Not an official FedRAMP or SBA determination.</p><p><a href="{base}/methodology/">Definitions, methods &amp; limitations</a><br/><a href="https://github.com/pete-wai/marketplace-smb/issues">Suggest a correction or additional evidence ↗</a></p></div></footer>
